const markdown = process.env.MARKDOWN;
if (!markdown) throw new Error('Missing MARKDOWN input');
const path = require('path');
const os = require('os');
const outPath = process.env.OUTPUT_PATH || path.join(os.tmpdir(), `md-${Date.now()}.pdf`);

const markdownPdf = require('markdown-pdf');
const fs = require('fs');
const path = require('path');
const os = require('os');
const tmpDir = os.tmpdir();
const mdFile = path.join(tmpDir, `md-${Date.now()}.md`);
fs.writeFileSync(mdFile, markdown);
await new Promise((resolve, reject) => {
  markdownPdf().from(mdFile).to(outPath, err => {
    if (err) reject(err);
    else resolve();
  });
});
